#define PI 3.1415926

vec2 fixUV(vec2 c) {                                           // uv coordinate

return 3.*(2.* c - iResolution.xy) / min(iResolution.x, iResolution.y); 

}


vec3 CCoord(vec2 uv){  

     vec2 cell = 1. - 2. * abs(fract(uv)-.5);  //draw grids

     vec3 col;

     col.rg = smoothstep( 1., -1., abs(uv.yx)/fwidth(uv.yx) -1. );  // axes 

     float a = max(col.g,col.r);                              // mask

     vec2 g = smoothstep( 2., 0., cell/(2.*fwidth(uv)) );    // grid

     return mix( vec3(max(g.x,g.y)), col, a );                // blending
}

float segment(in vec2 p, in vec2 a, in vec2 b, in float w){   /* The whole process here is trying to get the perpendicular distance from point p to vector ab .
                                                                 p are testing points which are everywhere on the screen.
                                                                 First we need to get the length of projection of ap onto ab. By doing dot(ap, ab), we 
                                                                 can get the result of multiplying the projection length (lets call it |ap'|) by the length of ab (|ab|). 
                                                                 Then divided by the result of dot product of ab and its self, obtaining |ap'| / |ab|
                                                                 The next step is to multiply (|ap'| / |ab|) by vector ab. 
                                                                 Please note that normalized vector = vector / |vector| (vector itself divided by its length)
                                                                 So for this step, what it all seems to boil down to is multiplying |ap'| by normalized vector ab,
                                                                 getting the vector ap'. Finally we can get vector p'p (perpendicular vector from p to ab) by subtracting
                                                                 ap' from ap. Lastly use length function to get its length, and the if function (now changed to smoothstep for antialiasing, thanks to FabriceNeyret2) means only return 1 (draw write)
                                                                 when |p'p| is less than w (the thickness of the line).
                                                                 If you don't understand the terms and math here I would recommend watching： Essence of Linear Algebra from 3 blue 1 brown's youtube channel
                                                              */


     float f = 0.;                                               

     vec2 ab = b - a;
     vec2 ap = p - a;

     float proj = clamp(dot(ap, ab) / dot(ab, ab), 0., 1.);

     float d = length( proj * ab - ap);


     return smoothstep( 1.5*length(fwidth(p)),0., d-w );;


}

float F1( in float a){                  // Defines the mathematical sine wave function, T oscillates with time.  
                                              // Produces the y-values for the sine wave.

    float T =  sin(iTime) * 2.  +5.;               

    return sin (3. * PI / T * a - iTime*2.);
}

float F2 (in vec2 uv){

 float a = uv.x * uv.x;
 float T = 3.*fwidth(uv.y);
 return smoothstep(-T, T  , T - abs(uv.y - a));


}

float funcPlot(in vec2 uv){

     float dx = fwidth(uv.x);                 // dx is offset value, and also the thickness of the line drawn

     return segment(uv, vec2(uv.x,F1(uv.x)), vec2(uv.x+dx,F1(uv.x+dx)), dx * 3.) +.1;


}



void mainImage( out vec4 fragColor, in vec2 fragCoord )
{

    vec2 uv = fixUV(fragCoord);

    vec3 color = CCoord(uv);

    color = mix(color, vec3(1., 1., 0.), funcPlot(uv));

    color = mix(color, vec3(1., 1., 0.), F2(uv));




    // Output to screen
    fragColor = vec4(color,1.0);
}
